files.content:
'use client';

// The documents screen: the workspace's Library is the list (`ListDetail`: beside the file on a wide screen, one pane at a time on a phone);
// the chosen file opens in the same viewer the Library uses (editable where it edits); its Revisions sit beside it. Every revision row opens
// that exact revision read-only, and « Back to editing » returns to the file. The editor stays mounted while a revision is inspected, so its
// unsaved edits survive; leaving the file with unsaved edits asks first. Every read goes through the one `revisionProvider` the host binds.
import { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import { Button } from '@/components/ui/button';
import { Separator } from '@/components/ui/separator';
import { createFileTreeController } from '@hachej/boring-ui-kit/file-tree';
import type { FileTreeController } from '@hachej/boring-ui-kit/file-tree';
import { FileTreeView } from '../file-tree/file-tree';
import type { RevisionProvider } from '@hachej/boring-files/revision';
import { mediaTypeOf, viewerKindOf } from '@hachej/boring-files/file-types';
import { checkBlobBase, withBlobPointers } from '@hachej/boring-files/blob';
import type { ViewerKind } from '@hachej/boring-files/file-types';
import { ListDetail } from '../app-shell/list-detail';
import { ArtifactPanel } from '../pi-app/artifact-panel';
import type { ArtifactDescriptor } from '../pi-chat/artifact';
import type { CustomViewers, ViewerOptions } from '../pi-app/artifact-panel';
import { FileViewer } from '../pi-app/file-viewer';
import { ImagePane } from '../viewers/image-pane';
import { PdfPane } from '../viewers/pdf-pane';
import { ViewerFrame } from '../viewers/viewer-frame';
import { useViewerText } from '../viewers/viewer-window';
import { cn } from '../utils/utils';
import { Revisions } from './revisions';
import type { DocumentsLabels } from './documents-labels';
import { documentsLabels, DocumentsWords } from './words';
import type { DocumentsLocale } from './words';

export interface DocumentsProps {
  /** The workspace's revision provider (the files guide's `connectRevisionProvider`, or a host's own binding). Borrowed: the host disposes it. */
  readonly provider: RevisionProvider;
  readonly locale?: DocumentsLocale | undefined;
  /** The block's own words, over `documentsLabels` (the viewers' words follow `locale`). */
  readonly labels?: Partial<DocumentsLabels> | undefined;
  /** Host viewers by kind, as for the Library (for example a canvas). */
  readonly viewers?: CustomViewers | undefined;
  readonly share?: ViewerOptions['share'];
  /** Where the host serves the bytes of large files (blob pointers): a same-origin path starting with `/`, default `/_files/`. */
  readonly blobBase?: string | undefined;
}

const nameOf = (path: string) => path.split('/').pop() || path;

/** The workspace's change feed as a counter: it moves on every change, so the listings and the revisions are read again. */
function useWorkspaceVersion(provider: RevisionProvider): number {
  const [version, setVersion] = useState(0);
  useEffect(() => {
    if (!provider.changes) return undefined;
    const abort = new AbortController();
    void (async () => {
      try { for await (const change of provider.changes!({ signal: abort.signal })) { void change; setVersion(current => current + 1); } } catch { /* the binding ended the feed: the listings stay as they are */ }
    })();
    return () => abort.abort();
  }, [provider]);
  return version;
}

/** The Library's tree over the provider: created and disposed with the binding, read again when the workspace changes. */
function useFileTree(provider: RevisionProvider, version: number, blobBase: string): FileTreeController | undefined {
  const [tree, setTree] = useState<FileTreeController>();
  useEffect(() => {
    const next = createFileTreeController({ revisionProvider: withBlobPointers(provider, blobBase) });
    setTree(next);
    void next.refresh();
    return () => next.dispose();
  }, [provider, blobBase]);
  useEffect(() => {
    if (!tree || version === 0) return;
    const { query, expanded } = tree.getSnapshot();
    if (query) void tree.search(query);
    else for (const directory of ['', ...expanded]) void tree.refresh(directory);
  }, [tree, version]);
  return tree;
}

/**
 * The provider as it reads one revision: every read of the returned client is the exact `revision`, over the same provider (a reload in a
 * pinned view re-reads that revision, never the latest). It is for read-only views only.
 */
function pinnedProviderOf(provider: RevisionProvider, revision: string): RevisionProvider {
  return { ...provider, read: (request, signal) => provider.read({ target: request.target, revision: { kind: 'exact', value: revision } }, signal) };
}

/** An image or PDF revision, read exactly and shown in the viewer's read-only pane. */
function BinaryRevision({ provider, path, revision, kind, labels, onClose }: {
  readonly provider: RevisionProvider;
  readonly path: string;
  readonly revision: string;
  readonly kind: 'image' | 'pdf';
  readonly labels: DocumentsLabels;
  readonly onClose: () => void;
}) {
  const [state, setState] = useState<{ readonly kind: 'loading' } | { readonly kind: 'failed' } | { readonly kind: 'ready'; readonly bytes: Uint8Array; readonly mediaType: string }>({ kind: 'loading' });
  const { labels: viewer } = useViewerText();
  useEffect(() => {
    const abort = new AbortController();
    setState({ kind: 'loading' });
    provider.read({ target: provider.locate(path), revision: { kind: 'exact', value: revision } }, abort.signal).then(result => {
      if (!abort.signal.aborted) setState(result.kind === 'available' ? { kind: 'ready', bytes: result.snapshot.bytes, mediaType: result.snapshot.mediaType } : { kind: 'failed' });
    }, () => { if (!abort.signal.aborted) setState({ kind: 'failed' }); });
    return () => abort.abort();
  }, [provider, path, revision]);
  const status = { label: viewer.readOnly, kind: 'read-only' as const };
  if (state.kind !== 'ready') return <ViewerFrame title={nameOf(path)} status={status} onClose={onClose}>
    <p role="status" className="m-0 p-4 text-sm text-muted-foreground">{state.kind === 'loading' ? labels.revisionsLoading : labels.revisionLoadFailed}</p>
  </ViewerFrame>;
  return kind === 'image'
    ? <ImagePane name={nameOf(path)} mediaType={state.mediaType} bytes={state.bytes} status={status} onClose={onClose} />
    : <PdfPane name={nameOf(path)} bytes={state.bytes} status={status} onClose={onClose} />;
}

/** One revision of the file, read-only, with « Back to editing ». Text, Markdown and HTML use the artifact panel's pinned view. */
function OlderVersion({ provider, path, revision, options, labels, onBack, onClose }: {
  readonly provider: RevisionProvider;
  readonly path: string;
  readonly revision: string;
  readonly options: ViewerOptions;
  readonly labels: DocumentsLabels;
  readonly onBack: () => void;
  readonly onClose: () => void;
}) {
  const kind: ViewerKind = viewerKindOf(path);
  const pinned = useMemo(() => pinnedProviderOf(provider, revision), [provider, revision]);
  const type = kind === 'markdown' ? 'markdown' : kind === 'html' ? 'html' : kind === 'text' ? 'code' : undefined;
  const artifact: ArtifactDescriptor | undefined = type === undefined ? undefined
    : { schema: 'boring.artifact', version: 1, title: nameOf(path), type, mediaType: mediaTypeOf(path), target: provider.locate(path), revision };
  const bar = <>
    <div className="flex shrink-0 items-center gap-2 px-3 py-2">
      <span role="status" className="min-w-0 flex-1 truncate text-sm font-medium">{labels.readOnlyRevision}</span>
      <Button variant="ghost" data-testid="back-to-editing" onClick={onBack}>{labels.backToEditing}</Button>
    </div>
    <Separator />
  </>;
  let body;
  if (artifact) body = <ArtifactPanel active={{ descriptor: artifact, follow: false }} versions={[]} options={{ ...options, client: pinned }} onSelect={onBack} onClose={onClose} />;
  else if (kind === 'image' || kind === 'pdf') body = <BinaryRevision provider={provider} path={path} revision={revision} kind={kind} labels={labels} onClose={onClose} />;
  else body = <ViewerFrame title={nameOf(path)} onClose={onClose}><p role="status" className="m-0 p-4 text-sm text-muted-foreground">{labels.unsupportedPreview}</p></ViewerFrame>;
  return <div data-testid="revision-view" data-kind={kind} data-revision={revision} className="flex h-full min-h-0 flex-1 flex-col">
    {bar}
    <div className="flex min-h-0 flex-1 flex-col">{body}</div>
  </div>;
}

function DocumentDetail({ provider, path, version, options, labels, locale, older, onDirty, onOpenRevision, onBack, onClose }: {
  readonly provider: RevisionProvider;
  readonly path: string;
  readonly version: number;
  readonly options: ViewerOptions;
  readonly labels: DocumentsLabels;
  readonly locale: DocumentsLocale;
  /** The older revision on show, `undefined` for the editable file. */
  readonly older: string | undefined;
  readonly onDirty: (unsaved: boolean) => void;
  readonly onOpenRevision: (revision: string) => void;
  readonly onBack: () => void;
  readonly onClose: () => void;
}) {
  return <div data-testid="documents-detail" className="flex h-full min-h-0 flex-col md:flex-row">
    <div className="flex min-h-0 min-w-0 flex-1 flex-col">
      {/* The editor stays mounted (hidden) while a revision is on show, so its unsaved edits are kept. */}
      <div className={cn('min-h-0 flex-1 flex-col', older === undefined ? 'flex' : 'hidden')}>
        <FileViewer path={path} locator={provider.locate(path)} options={options} onClose={onClose} onUnsavedChange={onDirty} />
      </div>
      {older !== undefined && <OlderVersion provider={provider} path={path} revision={older} options={options} labels={labels} onBack={onBack} onClose={onClose} />}
    </div>
    <Separator className="md:hidden" />
    <Separator orientation="vertical" className="max-md:hidden" />
    <aside className="flex max-h-[40%] min-h-0 shrink-0 flex-col overflow-hidden md:max-h-none md:w-72">
      <Revisions provider={provider} path={path} version={version} selected={older} locale={locale} labels={labels} onOpen={onOpenRevision} />
    </aside>
  </div>;
}

export function Documents({ provider, locale, labels: given, viewers, share, blobBase: givenBase }: DocumentsProps) {
  const labels = documentsLabels(locale, given);
  const language: DocumentsLocale = locale === 'fr' ? 'fr' : 'en';
  const version = useWorkspaceVersion(provider);
  const blobBase = checkBlobBase(givenBase);
  const tree = useFileTree(provider, version, blobBase);
  const [path, setPath] = useState<string>();
  // An older revision of the file on show (`undefined`: the editable file).
  const [pinned, setPinned] = useState<{ readonly path: string; readonly revision: string }>();
  // The file's unsaved edits, as its viewer reports them. A change of file or a close that would drop them asks first.
  const dirty = useRef(false);
  const onDirty = useCallback((unsaved: boolean) => { dirty.current = unsaved; }, []);
  const mayLeave = () => !dirty.current || window.confirm(labels.discardChanges);
  const options = useMemo<ViewerOptions>(() => ({ client: provider, identity: provider.identity, blobBase, ...(viewers ? { viewers } : {}), ...(share ? { share } : {}) }), [provider, viewers, share, blobBase]);
  const choose = (next: string) => {
    if (next === path || !mayLeave()) return;
    setPath(next);
    setPinned(undefined);
  };
  const closeFile = () => { if (!mayLeave()) return; setPath(undefined); setPinned(undefined); };
  const list = tree ? <div className="min-h-0">
    <FileTreeView controller={tree} onOpen={choose} selectedPath={path} locale={language} upload={false} history={false} />
  </div> : null;
  const older = path !== undefined && pinned?.path === path ? pinned.revision : undefined;
  // `null` (nothing chosen) is what lets a phone show the list alone: ListDetail stacks the detail only when there is one.
  const detail = path === undefined ? null
    : <DocumentDetail key={path} provider={provider} path={path} version={version} options={options} labels={labels} locale={language} older={older}
      onDirty={onDirty} onOpenRevision={revision => setPinned({ path, revision })} onBack={() => setPinned(undefined)} onClose={closeFile} />;
  return <DocumentsWords locale={locale}>
    <ListDetail list={list} detail={detail} onBack={closeFile} />
  </DocumentsWords>;
}

'use client';

// One document over the app, for « Voir la fiche »: the host sets `path` from its own handler (for example its `onOpenSpec`) and clears it in
// `onClose`. The sheet is a full-screen view of the shell (`useShellLayer`): it closes the agent layers when it opens, and Back closes it
// first. The file is the same viewer the Library opens (editable where the viewer edits). Closing a file with unsaved edits asks first.
// `onShowAll` adds « Toutes les fiches »: the sheet closes, then the host's navigation runs after the sheet's Back entry is gone.
import { useCallback, useEffect, useRef } from 'react';
import { Button } from '@/components/ui/button';
import { Drawer, DrawerContent, DrawerTitle } from '@/components/ui/drawer';
import { afterBack } from '../app-shell/back';
import { useShellLayer } from '../app-shell/shell-layer';
import { useExclusiveSheet } from '../app-shell/use-exclusive-sheet';
import { FileViewer } from '../pi-app/file-viewer';
import type { CustomViewers, ViewerOptions } from '../pi-app/artifact-panel';
import type { RevisionProvider } from '@hachej/boring-files/revision';
import { cn } from '../utils/utils';
import { documentsLabels, DocumentsWords } from './words';
import type { DocumentsLocale } from './words';
import type { DocumentsLabels } from './documents-labels';

export interface DocumentSheetProps {
  readonly provider: RevisionProvider;
  /** The workspace path of the document on show; `undefined` closes the sheet. */
  readonly path: string | undefined;
  /** Called when the sheet closes (its close button, a swipe, Back, « Toutes les fiches »): the host clears `path`. */
  readonly onClose: () => void;
  /** Adds « Toutes les fiches » to the sheet. The sheet closes first, then this runs. */
  readonly onShowAll?: (() => void) | undefined;
  readonly locale?: DocumentsLocale | undefined;
  readonly labels?: Partial<DocumentsLabels> | undefined;
  /** Host viewers by kind, as for the Library (for example a canvas). */
  readonly viewers?: CustomViewers | undefined;
  readonly share?: ViewerOptions['share'];
  readonly className?: string | undefined;
}

/** The sheet's name in the shell's layers: one sheet of this kind at a time. */
const LAYER = 'document';

export function DocumentSheet({ provider, path, onClose, onShowAll, locale, labels: given, viewers, share, className }: DocumentSheetProps) {
  const shown = path !== undefined;
  const labels = documentsLabels(locale, given);
  // The viewer reports its unsaved edits; a close that would drop them asks first (the Back path too, through the shell layer).
  const dirty = useRef(false);
  const report = useCallback((unsaved: boolean) => { dirty.current = unsaved; }, []);
  const mayLeave = () => !dirty.current || window.confirm(labels.discardChanges);
  const { open, close, isOpen } = useShellLayer(LAYER, { confirmBack: mayLeave });
  // The host's `path` decides whether the sheet is on show; a close from the sheet itself reports to the host.
  useEffect(() => { if (shown) open(); else close(); }, [shown, open, close]);
  useExclusiveSheet(isOpen, close);
  const wasOpen = useRef(false);
  useEffect(() => {
    if (shown && wasOpen.current && !isOpen) onClose();
    wasOpen.current = isOpen;
  }, [isOpen, shown, onClose]);
  const requestClose = () => { if (mayLeave()) close(); };
  const title = path === undefined ? labels.sheetTitle : path.split('/').pop() || path;
  return <DocumentsWords locale={locale}>
    <Drawer open={isOpen} onOpenChange={next => { if (!next) requestClose(); }} showSwipeHandle swipeDirection="down">
      <DrawerContent data-testid="document-sheet" className={cn('app-shell max-h-[92dvh] min-h-[92dvh]', className)}>
        {/* The title is for assistive technology: the viewer's own bar shows the file name. */}
        <DrawerTitle className="sr-only">{title}</DrawerTitle>
        {onShowAll && <div className="flex shrink-0 justify-end px-3 pt-1 pb-2">
          <Button variant="ghost" data-testid="document-sheet-all" onClick={() => { if (!mayLeave()) return; close(); afterBack(onShowAll); }}>{labels.allDocuments}</Button>
        </div>}
        <div className="flex min-h-0 flex-1 flex-col overflow-hidden pb-[env(safe-area-inset-bottom)]">
          {path !== undefined && <FileViewer key={path} path={path} locator={provider.locate(path)} onUnsavedChange={report}
            options={{ client: provider, identity: provider.identity, ...(viewers ? { viewers } : {}), ...(share ? { share } : {}) }} onClose={requestClose} />}
        </div>
      </DrawerContent>
    </Drawer>
  </DocumentsWords>;
}

'use client';

// The revisions of one file: what the workspace's history retains for it (`provider.history`, newest first), each with when it was saved and
// who wrote it (`source`). Every row opens that exact revision read-only; going back to editing is a separate control in the documents
// screen. The operation id is not shown: the public history carries none (a follow-up for the files seam).
import { useEffect, useState } from 'react';
import { Button } from '@/components/ui/button';
import { ScrollArea } from '@/components/ui/scroll-area';
import type { RevisionProvider, SavedRevision } from '@hachej/boring-files/revision';
import type { DocumentsLabels } from './documents-labels';

interface Loaded { readonly provider: RevisionProvider; readonly path: string; readonly saves: readonly SavedRevision[] }

/**
 * The retained revisions of `path` read from `provider`, read again when `version` changes. The answer is kept with the provider and the
 * path it was read for: another provider or path gets `undefined` at once, and a late answer for one of them is dropped.
 */
export function useRevisions(provider: RevisionProvider, path: string, version: number): readonly SavedRevision[] | undefined {
  const [loaded, setLoaded] = useState<Loaded>();
  useEffect(() => {
    const abort = new AbortController();
    const save = (saves: readonly SavedRevision[]) => { if (!abort.signal.aborted) setLoaded({ provider, path, saves }); };
    provider.history(path, abort.signal).then(save, () => save([]));
    return () => abort.abort();
  }, [provider, path, version]);
  return loaded && loaded.provider === provider && loaded.path === path ? loaded.saves : undefined;
}

/** When a revision was saved, in the page's language; `savedAt` 0 means the journal did not record a time. */
export function whenSaved(savedAt: number, locale: string, unknown: string): string {
  if (!savedAt) return unknown;
  return new Date(savedAt).toLocaleString(locale === 'fr' ? 'fr-FR' : 'en-GB', { dateStyle: 'medium', timeStyle: 'short' });
}

/** The panel's list: one row per retained revision, newest first. Each row opens its own revision read-only. */
export function Revisions({ provider, path, version, selected, locale, labels, onOpen }: {
  readonly provider: RevisionProvider;
  readonly path: string;
  /** Bumped when the workspace's change feed moves, so the list is read again. */
  readonly version: number;
  /** The revision on show in the read-only view, if any. */
  readonly selected: string | undefined;
  readonly locale: string;
  readonly labels: DocumentsLabels;
  readonly onOpen: (revision: string) => void;
}) {
  const saves = useRevisions(provider, path, version);
  return <section data-testid="revisions" aria-label={labels.revisions} className="flex min-h-0 flex-col">
    <h2 className="m-0 px-3 py-2 text-sm font-semibold">{labels.revisions}</h2>
    {saves === undefined ? <p role="status" className="m-0 px-3 pb-3 text-sm text-muted-foreground">{labels.revisionsLoading}</p>
      : saves.length === 0 ? <p role="status" className="m-0 px-3 pb-3 text-sm text-muted-foreground">{labels.noRevisions}</p>
      : <ScrollArea className="min-h-0 flex-1"><ol className="m-0 list-none p-1">
        {saves.map((save, index) => {
          const current = index === 0;
          const on = selected === save.revision;
          const when = whenSaved(save.savedAt, locale, labels.unknownTime);
          const who = save.source ? labels.savedBy[save.source] : labels.savedBy.observed;
          return <li key={save.revision}>
            <Button type="button" variant={on ? 'secondary' : 'ghost'} data-testid="revision-item" data-revision={save.revision} data-current={current ? 'true' : undefined}
              aria-current={on ? 'true' : undefined} aria-label={labels.openRevision(when)} onClick={() => onOpen(save.revision)}
              className="h-auto min-h-11 w-full flex-col items-start justify-start gap-0.5 whitespace-normal text-left">
              <span className="font-medium">{current ? labels.latest : when}</span>
              <span className="text-xs text-muted-foreground">{current ? `${when}, ${who}` : who}</span>
            </Button>
          </li>;
        })}
      </ol></ScrollArea>}
  </section>;
}

'use client';

// The words the documents block shows: its own, and the viewers' (the pi-app labels the file viewer and the artifact panel read, and the
// viewer window's labels the viewer bars read). One locale for all of them: `fr` takes the French sets, anything else English, and a
// `labels` object overrides any word of the block's own.
import type { ReactNode } from 'react';
import { defaultAppIcons, defaultAppLabels, AppTextProvider } from '../pi-app/app-labels';
import { frenchAppLabels } from '../pi-app/app-labels-fr';
import { defaultViewerIcons, defaultViewerLabels, ViewerWindowProvider } from '../viewers/viewer-window';
import { frenchViewerLabels } from '../viewers/viewer-labels-fr';
import { defaultDocumentsLabels, frenchDocumentsLabels } from './documents-labels';
import type { DocumentsLabels } from './documents-labels';

export type DocumentsLocale = 'en' | 'fr';

/** The block's own words for `locale`, with the host's overrides. */
export function documentsLabels(locale: DocumentsLocale | undefined, given: Partial<DocumentsLabels> | undefined): DocumentsLabels {
  return { ...(locale === 'fr' ? frenchDocumentsLabels : defaultDocumentsLabels), ...given };
}

/** Provides the app's and the viewers' words for `locale` to everything below (the file viewer, the artifact panel, the viewer bars). */
export function DocumentsWords({ locale, children }: { readonly locale: DocumentsLocale | undefined; readonly children: ReactNode }) {
  const fr = locale === 'fr';
  return <AppTextProvider value={{ labels: fr ? frenchAppLabels : defaultAppLabels, icons: defaultAppIcons }}>
    <ViewerWindowProvider value={{ labels: fr ? frenchViewerLabels : defaultViewerLabels, icons: defaultViewerIcons }}>{children}</ViewerWindowProvider>
  </AppTextProvider>;
}
